import (
    "os"
    "strconv"
    "strings"
)

type Weights struct {
    Mono []int
    Bi [][]int
}

func isLetter(c byte) bool {
    return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z'
}

func letterValue(c byte) int {
    if c >= 'a' && c <= 'z' {
        return int(c - 'a')
    }
    return int(c - 'A')
}

func uppercase(value int) byte {
    return byte('A' + value)
}

func letters(text string) string {
    var out strings.Builder
    for i := 0; i < len(text); i++ {
        c := text[i]
        if !isLetter(c) {
            continue
        }
        out.WriteByte(uppercase(letterValue(c)))
    }
    return out.String()
}

func groups(text string) []string {
    result := []string{}
    batch := []string{}
    for i := 0; i < len(text); i += 5 {
        end := i + 5
        if end > len(text) {
            end = len(text)
        }
        batch = append(batch, text[i:end])
        if len(batch) == 10 {
            result = append(result, strings.Join(batch, " "))
            batch = []string{}
        }
    }
    if len(batch) > 0 {
        result = append(result, strings.Join(batch, " "))
    }
    return result
}

func monogram(text string, weights []int) int {
    result := 0
    for i := 0; i < len(text); i++ {
        result += weights[int(text[i] - 'A')]
    }
    return result
}

func bigram(text string, weights [][]int) int {
    result := 0
    for i := 1; i < len(text); i++ {
        result += weights[int(text[i - 1] - 'A')][int(text[i] - 'A')]
    }
    return result
}

func readWeights(path string) Weights {
    data, err := os.ReadFile(path)
    if err != nil {
        panic(err)
    }
    lines := strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
    parse := func(line string) []int {
        fields := strings.Split(line, " ")
        values := make([]int, len(fields))
        for i, word := range fields {
            value, err := strconv.Atoi(word)
            if err != nil {
                panic(err)
            }
            values[i] = value
        }
        return values
    }
    result := Weights{Mono: parse(lines[1]), Bi: make([][]int, 26)}
    for i := 0; i < 26; i++ {
        result.Bi[i] = parse(lines[i + 3])
    }
    return result
}

package main

import (
    "strconv"
    "strings"
)

func modulo(value int, modulus int) int {
    return (value%modulus + modulus) % modulus
}

func inverse(a int) int {
    for i := 1; i < 26; i++ {
        if (a*i)%26 == 1 {
            return i
        }
    }
    panic("noninvertible affine key")
}

func substitute(text, cipher, key string, encrypt bool) string {
    a, b := 1, 0
    if cipher == "caesar" {
        b, _ = strconv.Atoi(key)
    } else if cipher == "affine" {
        parts := strings.Split(key, ",")
        a, _ = strconv.Atoi(parts[0])
        b, _ = strconv.Atoi(parts[1])
    }
    inverseA := 1
    if cipher == "affine" {
        inverseA = inverse(a)
    }
    plain := []int{}
    var output strings.Builder
    index := 0
    for i := 0; i < len(text); i++ {
        c := text[i]
        if !isLetter(c) {
            output.WriteByte(c)
            continue
        }
        x, shift := letterValue(c), 0
        if cipher == "vigenere" {
            shift = letterValue(key[index%len(key)])
        } else if cipher == "autokey" {
            if index < len(key) {
                shift = letterValue(key[index])
            } else {
                shift = plain[index-len(key)]
            }
        }
        y := 0
        switch cipher {
        case "caesar":
            if encrypt {
                y = modulo(x+b, 26)
            } else {
                y = modulo(x-b, 26)
            }
        case "affine":
            if encrypt {
                y = modulo(a*x+b, 26)
            } else {
                y = modulo(inverseA*(x-b), 26)
            }
        case "vigenere", "autokey":
            if encrypt {
                y = modulo(x+shift, 26)
            } else {
                y = modulo(x-shift, 26)
            }
        }
        if encrypt {
            plain = append(plain, x)
        } else {
            plain = append(plain, y)
        }
        base := byte('A')
        if c >= 'a' {
            base = 'a'
        }
        output.WriteByte(base + byte(y))
        index++
    }
    return output.String()
}

package main

import (
    "sort"
    "strings"
)

func railNumber(position, rails int) int {
    cycle := 2*rails - 2
    offset := position % cycle
    if offset < cycle-offset {
        return offset
    }
    return cycle-offset
}

func railFence(text string, rails int, encrypt bool) string {
    order := make([]int, len(text))
    for i := range order {
        order[i] = i
    }
    sort.Slice(order, func(i, j int) bool {
        left, right := railNumber(order[i], rails), railNumber(order[j], rails)
        if left != right {
            return left < right
        }
        return order[i] < order[j]
    })
    result := make([]byte, len(text))
    for index, position := range order {
        if encrypt {
            result[index] = text[position]
        } else {
            result[position] = text[index]
        }
    }
    return string(result)
}

func columnOrder(key string) []int {
    order := make([]int, len(key))
    for i := range order {
        order[i] = i
    }
    sort.Slice(order, func(i, j int) bool {
        if key[order[i]] != key[order[j]] {
            return key[order[i]] < key[order[j]]
        }
        return order[i] < order[j]
    })
    return order
}

func rankString(key string) string {
    result := make([]byte, len(key))
    for rank, position := range columnOrder(key) {
        result[position] = byte('1' + rank)
    }
    return string(result)
}

func columnar(text, key string, encrypt bool) string {
    var output strings.Builder
    if encrypt {
        for _, col := range columnOrder(key) {
            for i := col; i < len(text); i += len(key) {
                output.WriteByte(text[i])
            }
        }
        return output.String()
    }
    result := make([]byte, len(text))
    position := 0
    for _, col := range columnOrder(key) {
        for i := col; i < len(text); i += len(key) {
            result[i] = text[position]
            position++
        }
    }
    return string(result)
}
